using static StrataLint.Scribe.DefinitionDsl;

namespace StrataLint.Scribe.Blueprint.D5.S3.VertexAlgebra.Lattice;

internal sealed class OrderedHyperbolicExtensionDocument : IScribeDocumentDefinition
{
    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "Ordered integral hyperbolic extension", H("Ordered integral hyperbolic extension"), Blocks(
            Paragraph(Text("The finite coordinates remain the original ordered Fin(rank+2): the old coordinates precede m and n. The literal new block has zero diagonal and off-diagonal entries one. The full pairing is B(a,b)+m*s+n*r, the charge energy is energy(a)+m*n, and the canonical LOWER cocycle adds n*r. No charge is removed. The inverse is the old integral inverse and the same U block. Its two multiplication equations are proved before casting to the complex Gram inverse. The real subspaces (x,t,t) and (0,t,-t) give signature (rank+1,1) when the old real Gram matrix is positive definite; they do not change integral coordinates or the hyperbolic normalization.")),
            Describe.Lean(DescribeId.Create("orderedhyperbolicextension-0"), DeclarationHandle.Create("D5/S3/VertexAlgebra/Lattice/OrderedHyperbolicExtension.extend"), H("The ordered block construction"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("The old Gram block is followed by the literal matrix with zero diagonal and both off-diagonal entries one, using the old-then-m,n finite order."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("orderedhyperbolicextension-1"), DeclarationHandle.Create("D5/S3/VertexAlgebra/Lattice/OrderedHyperbolicExtension.lowerCocycleExponent_splice"), H("The exact ordered lower cocycle"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("For arbitrary old charges a,b and integers m,n,r,s, the original lower-triangle exponent is lower(a,b)+n*r."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("orderedhyperbolicextension-2"), DeclarationHandle.Create("D5/S3/VertexAlgebra/Lattice/OrderedHyperbolicExtension.integerInverse_left"), H("The constructed left inverse"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("The literal reindexed block matrix with blocks G inverse and U multiplies the extended integral Gram matrix to the identity."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("orderedhyperbolicextension-3"), DeclarationHandle.Create("D5/S3/VertexAlgebra/Lattice/OrderedHyperbolicExtension.integerInverse_right"), H("The constructed right inverse"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("The extended integral Gram matrix multiplies the same constructed integral inverse to the identity."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("orderedhyperbolicextension-4"), DeclarationHandle.Create("D5/S3/VertexAlgebra/Lattice/OrderedHyperbolicExtension.signature_extend"), H("Signature from explicit real subspaces"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("The images of (x,t) mapped to (x,t,t) and t mapped to (0,t,-t) have proved dimensions rank+1 and one and positive and negative restricted quadratic forms."))), DescribeRole.Theorem))));
}
